188	        this.householdId = householdId;
189	    }
190	
191	    /**
192	     * The number of owners in this owner's household (owners sharing its householdId, counting
193	     * this owner). Not a persisted column — populated by the owner pipelines (create and read)
194	     * that have repository access, and consumed only by {@link #getMembershipPoints()}. {@code
195	     * null} when it has not been resolved, which the points rule treats as a single-member
196	     * household.
197	     */
198	    @Transient
199	    public Integer getHouseholdSize() {
